int virtio_gpu_create_object(struct virtio_gpu_device *vgdev, unsigned long size,
                             bool kernel, bool pinned, struct virtio_gpu_object **bo_ptr) {
    struct virtio_gpu_object *bo;
    int ret;

    // Determine buffer object type
    unsigned int type = kernel ? VIRGL_OBJ_TYPE_KERNEL : VIRGL_OBJ_TYPE_USER;

    // Calculate required size
    size_t obj_size = sizeof(*bo) + size;

    // Allocate memory for the GPU object
    bo = kzalloc(obj_size, GFP_KERNEL);
    if (!bo)
        return -ENOMEM;

    // Initialize the object
    bo->size = size;
    bo->type = type;
    bo->pinned = pinned;

    // Setup placement
    if (pinned) {
        ret = virtio_gpu_pin_bo(vgdev, bo);
        if (ret < 0) {
            kfree(bo);
            return ret;
        }
    }

    // Assign the created object to the provided pointer
    *bo_ptr = bo;
    return 0;
}

